        ((Moby *)m)->draw_dist = 0xFF;
        d = ((char *)((Moby *)m)->pvars);
        ((Moby *)m)->rot.z = rz;
        ((Moby *)m)->rot.y = ry;
        if (tgt == 0) {
            BuildSphericalOffset(&t, g_frame_time * 20.0f, rz, ry);
            p.q = *(Q_2aa998 *)pos;
            tgt = select_auto_aim_target_moby(owner, &p, &t, &a, &b, &c, 0.34906584f);
        }
        *(void **)(d + 0x10) = owner;
        qcopy(m + 0x10, pos);
        *(float *)(d + 0x34) = g_frame_time * 100.0f;
        *(int *)(d + 0x38) = 1;
        *(int *)(d + 0x24) = 0;
        *(int *)(d + 0x28) = 0;
        *(int *)(d + 0x20) = 0;
        *(char **)(d + 0x18) = tgt;
        if (tgt != 0) {
            unsigned char *e = (unsigned char *)GetFlaggedPvarWord(tgt);
            if (e != 0) {
                *(unsigned short *)(e + 0x1E) |= 0x80;
                if (e[0xB] != 0) *(int *)(d + 0x38) = 0;
                if (e[0xC] != 0) *(float *)(d + 0x34) = (float)e[0xC] * g_frame_time;
            }
        }
        *(float *)(d + 0x2C) = a;
        *(float *)(d + 0x30) = b;
        *(int *)(d + 0x14) = scale_ticks(0x96);
        if (tgt != 0) {
            qcopy(d, tgt + 0x10);
            *(float *)(d + 8) += c;
            *(float *)(d + 0x1C) = c;
        }
        {
            int r;
            if (FastVecLength((float *)(g_hero + 0x140)) > g_frame_time * 0.1f) {
                r = scale_ticks(0x3C);
                *(short *)(d + 0x3E) = r;
                *(short *)(d + 0x3C) = r;
            } else {
                r = scale_ticks(1);
                *(short *)(d + 0x3E) = r;
                *(short *)(d + 0x3C) = r;
            }
        }
        t.q = ((BoltOwner_2AA998 *)owner)->position.q;
